const rows = $input.all();
const row = rows.find(r => (r.json.Status || '').toUpperCase() === 'PENDING');
if (!row) return [{json: {found: false, topic: null, rowNumber: null}}];
return [{json: {found: true, topic: row.json.Topic, rowNumber: row.json.row_number}}];

const items = $input.all();

function getText(item) {
  const c = item && item.json && item.json.content;
  if (Array.isArray(c) && c[0] && c[0].text) return c[0].text.trim();
  return '';
}

const script = getText(items[0]);
const rawTitle = getText(items[1]);
const description = getText(items[2]);
const rawTags = getText(items[3]);

const title = rawTitle.split('\n')[0].replace(/^["'\s]+|["'\s]+$/g,'').slice(0,100);

let tags = [];
try {
  const m = rawTags.match(/\[[\s\S]*?\]/);
  if (m) tags = JSON.parse(m[0]);
} catch(e) {
  tags = rawTags.split(',').map(t => t.trim().replace(/["\[\]]/g,'')).filter(Boolean);
}
tags = tags.slice(0,15);

const ttsLines = script.split('\n').filter(l => l.trim() && !l.startsWith('[') && !l.startsWith('('));
const ttsText = ttsLines.join(' ').slice(0, 2500);

const topic = $('🧠 Build Prompt Context').item(0).json.topic;
const rowNumber = $('🧠 Build Prompt Context').item(0).json.rowNumber;
const thumbnailPrompt = $('🧠 Build Prompt Context').item(0).json.thumbnailPrompt;

return [{json:{script, title, description, tags, ttsText, ttsLines, topic, rowNumber, thumbnailPrompt}}];

const copy = $('⚙️ Parse & Format Copy').item(0).json;
const driveFileId = $('☁️ Upload Audio to Drive').item(0).json.id;
const audioUrl = 'https://drive.google.com/uc?export=download&id=' + driveFileId;
const characterUrl = $env.SNIFFLE_PAWS_PNG_URL || 'https://drive.google.com/uc?id=' + ($env.SNIFFLE_PAWS_DRIVE_ID || 'YOUR_CHARACTER_PNG_DRIVE_ID');

const lines = (copy.ttsLines || []).slice(0, 26);
const palette = ['#FF6B6B','#FFE66D','#4ECDC4','#FF9F43','#A29BFE','#FD79A8','#55EFC4','#FDCB6E','#74B9FF','#81ECEC','#FAB1A0','#00B894'];

const secPerLine = 3.5;
const introDur = 3;
const outroDur = 4;
const totalDur = introDur + (lines.length * secPerLine) + outroDur;

const bgTrack = [];
const textTrack = [];

bgTrack.push({asset:{type:'shape',shape:'rectangle',width:1,height:1,color:'#FFE66D'},start:0,length:introDur});
textTrack.push({asset:{type:'html',html:'<p>' + copy.topic + '!</p>',width:960,height:220,css:'p{font-family:Arial Black,Arial,sans-serif;color:#FF6B6B;font-size:90px;font-weight:900;text-align:center;text-shadow:5px 5px 0 #fff,6px 6px 0 rgba(0,0,0,0.1);}'},start:0,length:introDur,position:'center'});

lines.forEach((line, i) => {
  const start = introDur + (i * secPerLine);
  const color = palette[i % palette.length];
  const safe = line.replace(/[<>&"]/g,'').trim().slice(0,72);
  bgTrack.push({asset:{type:'shape',shape:'rectangle',width:1,height:1,color},start,length:secPerLine});
  textTrack.push({asset:{type:'html',html:'<p>' + safe + '</p>',width:900,height:280,css:'p{font-family:Arial Black,Arial,sans-serif;color:#fff;font-size:58px;font-weight:900;text-align:center;text-shadow:3px 3px 0 rgba(0,0,0,0.25);line-height:1.15;}'},start,length:secPerLine,position:'center',offset:{x:0.09,y:0}});
});

const outroStart = totalDur - outroDur;
bgTrack.push({asset:{type:'shape',shape:'rectangle',width:1,height:1,color:'#4ECDC4'},start:outroStart,length:outroDur});
textTrack.push({asset:{type:'html',html:'<p>Subscribe!</p>',width:700,height:200,css:'p{font-family:Arial Black,Arial,sans-serif;color:#FFE66D;font-size:82px;font-weight:900;text-align:center;text-shadow:4px 4px 0 rgba(0,0,0,0.2);}'},start:outroStart,length:outroDur,position:'center'});

const charTrack = [{asset:{type:'image',src:characterUrl},start:0,length:totalDur,position:'bottomLeft',offset:{x:0.02,y:-0.02},scale:0.28,effect:'zoomIn'}];

const renderBody = {
  timeline:{
    background:{color:'#FFE66D'},
    soundtrack:{src:audioUrl,effect:'fadeInFadeOut',volume:1},
    tracks:[{clips:textTrack},{clips:charTrack},{clips:bgTrack}]
  },
  output:{format:'mp4',resolution:'hd',aspectRatio:'16:9',fps:25}
};

return [{json:{renderBody, totalDur, topic:copy.topic, rowNumber:copy.rowNumber}}];

const now = new Date();
const day = now.getUTCDay();
const isWeekend = day === 0 || day === 6;
const peakHourEST = isWeekend ? 9 : 15;
const peakHourUTC = peakHourEST + 5;

const publish = new Date(now);
publish.setUTCHours(peakHourUTC, 0, 0, 0);

if (publish.getTime() <= now.getTime()) {
  publish.setUTCDate(publish.getUTCDate() + 1);
  const nextDay = publish.getUTCDay();
  const nextIsWeekend = nextDay === 0 || nextDay === 6;
  publish.setUTCHours((nextIsWeekend ? 9 : 15) + 5, 0, 0, 0);
}

const publishAt = publish.toISOString().replace('.000Z', '+00:00');
const videoId = $('📤 Upload Video to YouTube').item(0).json.id;

return [{json:{publishAt, videoId, isWeekend, peakHourEST}}];
